// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

/// @title Sistema de Certificación Académica
/// @notice Permite a un administrador autorizar instructores y consultar la lista de instructores autorizados
contract Certificado {
    // Dirección del administrador del contrato (quien despliega)
    address public administrador;

    // Mapeo para verificar si una dirección está autorizada como instructor
    mapping(address => bool) public instructoresAutorizados;

    // Lista dinámica de instructores autorizados (para consulta)
    address[] public listaInstructores;

    /// @notice Evento emitido cuando se autoriza un nuevo instructor
    event InstructorAutorizado(address indexed instructor);

    /// @dev Constructor: se ejecuta al desplegar el contrato y define al administrador
    constructor() {
        administrador = msg.sender;
    }

    /// @dev Modificador que restringe funciones solo al administrador
    modifier soloAdmin() {
        require(msg.sender == administrador, "No autorizado");
        _;
    }

    /// @notice Autoriza una dirección como instructor (solo admin)
    /// @param _instructor Dirección del instructor a autorizar
    function autorizarInstructor(address _instructor) public soloAdmin {
        require(!instructoresAutorizados[_instructor], "Ya autorizado");
        instructoresAutorizados[_instructor] = true;
        listaInstructores.push(_instructor);
        emit InstructorAutorizado(_instructor);
    }

    /// @notice Devuelve la lista completa de instructores autorizados
    /// @return Arreglo de direcciones de instructores autorizados
    function obtenerInstructores() public view returns (address[] memory) {
        return listaInstructores;
    }
}

